require_once __DIR__.'/../includes/auth.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['error'=>'Method not allowed'],405);verify_api_csrf();$in=json_decode(file_get_contents('php://input'),true)??[];$cid=filter_var($in['conversation_id']??null,FILTER_VALIDATE_INT);$message=trim((string)($in['message']??''));$reply=filter_var($in['reply_to_id']??null,FILTER_VALIDATE_INT)?:null;$uid=current_user_id();if(!$cid||!is_member($pdo,$cid,$uid))json_response(['error'=>'Not allowed'],403);if($message===''||mb_strlen($message)>4000)json_response(['error'=>'Message must contain 1–4000 characters.'],422);if($reply){$st=$pdo->prepare('SELECT message_id FROM messages WHERE message_id=? AND conversation_id=?');$st->execute([$reply,$cid]);if(!$st->fetchColumn())$reply=null;}
$st=$pdo->prepare("INSERT INTO messages(conversation_id,sender_id,message_text,reply_to_id) VALUES(?,?,?,?)");$st->execute([$cid,$uid,$message,$reply]);$mid=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE conversations SET updated_at=NOW() WHERE conversation_id=?')->execute([$cid]);$st=$pdo->prepare("SELECT u.user_id,u.full_name FROM conversation_members cm JOIN users u ON u.user_id=cm.user_id WHERE cm.conversation_id=? AND cm.user_id<>?");$st->execute([$cid,$uid]);foreach($st->fetchAll() as $recipient){$pdo->prepare("INSERT INTO notifications(user_id,conversation_id,message_id,notification_type,body) VALUES(?,?,?,'message',?)")->execute([$recipient['user_id'],$cid,$mid,mb_strimwidth($_SESSION['full_name'].': '.$message,0,240,'…')]);}
json_response(['ok'=>true,'message_id'=>$mid]);
